export const PATTERN_BACKGROUND_VARIANT = {
    Grid: "grid",
    Dot: "dot",
    BigDot: "big-dot",
} as const;

export const PATTERN_BACKGROUND_SPEED = {
    Default: 10000,
    Slow: 25000,
    Fast: 5000,
} as const;

