	let frameBuffer = new Uint8Array(0);

	// Fixed part of the image.
	// 点阵掩码缓冲区（标记不可变区域） - 先初始化为空数组，后面会重新赋值
	let frameMask = new Uint8Array(0);

	// Generator polynomial.
	// 生成多项式缓冲区（纠错码计算用） - 先初始化为空数组，后面会重新赋值
	let polynomial = new Uint8Array(0);

	// Data input buffer.
	// 数据输入缓冲区 - 先初始化为空数组，后面会重新赋值
	let stringBuffer = new Uint8Array(0);

	/**
	 * 设置掩码位，表示该点为不可变区域（对称处理）
	 * @param _x 横坐标
	 * @param _y 纵坐标
	 */
	function setMask(_x: number, _y: number) {
		let bit: number;
		let x = _x;
		let y = _y;

		if (x > y) {
			bit = x;
			x = y;
			y = bit;
		}

		bit = y;
		bit *= y;
		bit += y;
		bit >>= 1;
		bit += x;

		frameMask[bit] = 1;
	}

	/**
	 * 添加对齐块，设置对应点阵和掩码
	 * @param _x 横坐标
	 * @param _y 纵坐标
	 */
	function addAlignment(_x: number, _y: number) {
		let i: number;
		let x = _x;
		let y = _y;

		frameBuffer[x + width * y] = 1;

		for (i = -2; i < 2; i++) {
			frameBuffer[x + i + width * (y - 2)] = 1;
			frameBuffer[x - 2 + width * (y + i + 1)] = 1;
			frameBuffer[x + 2 + width * (y + i)] = 1;
			frameBuffer[x + i + 1 + width * (y + 2)] = 1;
		}

		for (i = 0; i < 2; i++) {
			setMask(x - 1, y + i);
			setMask(x + 1, y - i);
			setMask(x - i, y - 1);
			setMask(x + i, y + 1);
		}

		for (i = 2; i < 4; i++) {
			frameBuffer[x + i + width * (y - 2)] = 1;
			frameBuffer[x - 2 + width * (y + i - 1)] = 1;
			frameBuffer[x + 2 + width * (y + i - 2)] = 1;
			frameBuffer[x - 1 + width * (y + i - 2)] = 1;
		}
	}

	/**
	 * Galois 域取模运算
	 * @param _x 输入数值
	 * @returns {number} 取模结果
	 */
	function modN(_x: number): number {
		var x = _x;
		while (x >= 255) {
			x -= 255;
			x = (x >> 8) + (x & 255);
		}

		return x;
	}

	/**
	 * 计算并追加纠错码到数据块
	 * @param _data 数据起始索引
	 * @param _dataLength 数据长度
	 * @param _ecc 纠错码起始索引
	 * @param _eccLength 纠错码长度
	 */
	function appendData(_data: number, _dataLength: number, _ecc: number, _eccLength: number) {
		let bit: number;
		let i: number;
		let j: number;
		let data = _data;
		let dataLength = _dataLength;
		let ecc = _ecc;
		let eccLength = _eccLength;

		for (i = 0; i < eccLength; i++) {
			stringBuffer[ecc + i] = 0;
		}

		for (i = 0; i < dataLength; i++) {
			bit = GALOIS_LOG[stringBuffer[data + i] ^ stringBuffer[ecc]];

			if (bit != 255) {
				for (j = 1; j < eccLength; j++) {
					stringBuffer[ecc + j - 1] =
						stringBuffer[ecc + j] ^
						GALOIS_EXPONENT[modN(bit + polynomial[eccLength - j])];
				}
			} else {
				for (j = ecc; j < ecc + eccLength; j++) {
					stringBuffer[j] = stringBuffer[j + 1];
				}
			}

			stringBuffer[ecc + eccLength - 1] =
				bit == 255 ? 0 : GALOIS_EXPONENT[modN(bit + polynomial[0])];
		}
	}

	/**
	 * 判断某点是否为掩码区域
	 * @param _x 横坐标
	 * @param _y 纵坐标
	 * @returns {boolean} 是否为掩码
	 */
	function isMasked(_x: number, _y: number): boolean {
		let bit: number;
		let x = _x;
		let y = _y;

		if (x > y) {
			bit = x;
			x = y;
			y = bit;
		}

		bit = y;
		bit += y * y;
		bit >>= 1;
		bit += x;
		return frameMask[bit] == 1;
	}

	/**
	 * 根据 QR Code 标准，应用指定的掩码 pattern
	 * @param mask 掩码编号 (0-7)
	 */
	function applyMask(mask: number) {
		for (let y = 0; y < width; y++) {
			for (let x = 0; x < width; x++) {
				if (!isMasked(x, y)) {
					let shouldInvert = false;
					switch (mask) {
						case 0:
							shouldInvert = (x + y) % 2 == 0;
							break;
						case 1:
							shouldInvert = y % 2 == 0;
							break;
						case 2:
							shouldInvert = x % 3 == 0;
							break;
						case 3:
							shouldInvert = (x + y) % 3 == 0;
							break;
						case 4:
							shouldInvert = (Math.floor(y / 2) + Math.floor(x / 3)) % 2 == 0;
							break;
						case 5:
							shouldInvert = ((x * y) % 2) + ((x * y) % 3) == 0;
							break;
						case 6:
							shouldInvert = (((x * y) % 2) + ((x * y) % 3)) % 2 == 0;
							break;
						case 7:
							shouldInvert = (((x + y) % 2) + ((x * y) % 3)) % 2 == 0;
							break;
					}

					if (shouldInvert) {
						frameBuffer[x + y * width] ^= 1;
					}
				}
			}
		}
	}

	/**
	 * 计算连续同色块的"坏度"分数
	 * @param runLengths
	 * @param length 块长度
	 * @returns {number} 坏度分数
	 */
	function getBadRuns(runLengths: number[], length: number): number {
		let badRuns = 0;
		let i: number;

		for (i = 0; i <= length; i++) {
			if (i < runLengths.length && runLengths[i] >= 5) {
				badRuns += N1 + runLengths[i] - 5;
			}
		}

		// FBFFFBF as in finder.
		for (i = 3; i < length - 1; i += 2) {
			// 检查数组索引是否越界
			if (i + 2 >= runLengths.length || i - 3 < 0) {
				continue;
			}

			if (
				runLengths[i - 2] == runLengths[i + 2] &&
				runLengths[i + 2] == runLengths[i - 1] &&
				runLengths[i - 1] == runLengths[i + 1] &&
				runLengths[i - 1] * 3 == runLengths[i] &&
				// Background around the foreground pattern? Not part of the specs.
				(runLengths[i - 3] == 0 ||
					i + 3 > length ||
					runLengths[i - 3] * 3 >= runLengths[i] * 4 ||
					runLengths[i + 3] * 3 >= runLengths[i] * 4)
			) {
				badRuns += N3;
			}
		}

		return badRuns;
	}

	/**
	 * 评估当前二维码点阵的整体"坏度"
	 * @returns {number} 坏度分数
	 */
	function checkBadness(): number {
		let b: number;
		let b1: number;
		let bad = 0;
		let big: number;
		let bw = 0;
		let count = 0;
		let h: number;
		let x: number;
		let y: number;
		// 优化：在函数内创建badBuffer，避免外部变量的内存泄漏风险
		let badBuffer = new Array<number>(width);

		// Blocks of same colour.
		for (y = 0; y < width - 1; y++) {
			for (x = 0; x < width - 1; x++) {
				// All foreground colour.
				if (
					(frameBuffer[x + width * y] == 1 &&
						frameBuffer[x + 1 + width * y] == 1 &&
						frameBuffer[x + width * (y + 1)] == 1 &&
						frameBuffer[x + 1 + width * (y + 1)] == 1) ||
					// All background colour.
					(frameBuffer[x + width * y] == 0 &&
						frameBuffer[x + 1 + width * y] == 0 &&
						frameBuffer[x + width * (y + 1)] == 0 &&
						frameBuffer[x + 1 + width * (y + 1)] == 0)
				) {
					bad += N2;
				}
			}
		}

		// X runs
		for (y = 0; y < width; y++) {
			h = 0;
			badBuffer[h] = 0;
			b = 0;
			for (x = 0; x < width; x++) {
				b1 = frameBuffer[x + width * y];
				if (b1 == b) {
					if (h < badBuffer.length) {
						badBuffer[h]++;
					}
				} else {
					h++;

					if (h < badBuffer.length) {
						badBuffer[h] = 1;
					}
				}

				b = b1;
				bw += b > 0 ? 1 : -1;
			}

			bad += getBadRuns(badBuffer, h);
		}

		if (bw < 0) bw = -bw;

		big = bw;
		big += big << 2;
		big <<= 1;

		while (big > width * width) {
			big -= width * width;
			count++;
		}

		bad += count * N4;

		// Y runs.
		for (x = 0; x < width; x++) {
			h = 0;
			badBuffer[h] = 0;
			b = 0;
			for (y = 0; y < width; y++) {
				b1 = frameBuffer[x + width * y];
				if (b1 == b) {
					if (h < badBuffer.length) {
						badBuffer[h]++;
					}
				} else {
					h++;
					if (h < badBuffer.length) {
						badBuffer[h] = 1;
					}
				}

				b = b1;
			}

			bad += getBadRuns(badBuffer, h);
		}

		return bad;
	}

	/**
	 * 将字符串转为 UTF-8 编码，兼容多平台
	 * @param str 输入字符串
	 * @returns {string} UTF-8 编码字符串
	 */
	function toUtf8(str: string): string {
		let out = "";
		let i: number;
		let len: number;
		let c: number;
		len = str.length;
		for (i = 0; i < len; i++) {
			c = str.charCodeAt(i)!;
			if (c >= 0x0001 && c <= 0x007f) {
				out += str.charAt(i);
			} else if (c > 0x07ff) {
				out += String.fromCharCode(0xe0 | ((c >> 12) & 0x0f));
				out += String.fromCharCode(0x80 | ((c >> 6) & 0x3f));
				out += String.fromCharCode(0x80 | ((c >> 0) & 0x3f));
			} else {
				out += String.fromCharCode(0xc0 | ((c >> 6) & 0x1f));
				out += String.fromCharCode(0x80 | ((c >> 0) & 0x3f));
			}
		}
		return out;
	}
	//end functions

	// Find the smallest version that fits the string.
	// 1. 字符串转 UTF-8，计算长度
	str = toUtf8(str);
	t = str.length;

	// 2. 自动选择最小可用版本
	version = 0;
	do {
		version++;
		k = (eccLevel - 1) * 4 + (version - 1) * 16;
		neccBlock1 = ECC_BLOCKS[k++];
		neccBlock2 = ECC_BLOCKS[k++];
		dataBlock = ECC_BLOCKS[k++];
		eccBlock = ECC_BLOCKS[k];

		k = dataBlock * (neccBlock1 + neccBlock2) + neccBlock2 - 3 + (version <= 9 ? 1 : 0);

		if (t <= k) break;
	} while (version < 40);

	// FIXME: Ensure that it fits insted of being truncated.
	// 3. 计算二维码宽度
	width = 17 + 4 * version;

	// Allocate, clear and setup data structures.
	// 4. 分配缓冲区, 使用定长的 Uint8Array 优化内存
	v = dataBlock + (dataBlock + eccBlock) * (neccBlock1 + neccBlock2) + neccBlock2;
	eccBuffer = new Uint8Array(v);
	stringBuffer = new Uint8Array(v);

	// 5. 预分配点阵、掩码缓冲区
	frameBuffer = new Uint8Array(width * width);
	frameMask = new Uint8Array(Math.floor((width * (width + 1) + 1) / 2));

	// Insert finders: Foreground colour to frame and background to mask.
	// 插入定位点: 前景色为二维码，背景色为掩码
	for (t = 0; t < 3; t++) {
		k = 0;
		y = 0;
		if (t == 1) k = width - 7;
		if (t == 2) y = width - 7;

		frameBuffer[y + 3 + width * (k + 3)] = 1;

		for (x = 0; x < 6; x++) {
			frameBuffer[y + x + width * k] = 1;
			frameBuffer[y + width * (k + x + 1)] = 1;
			frameBuffer[y + 6 + width * (k + x)] = 1;
			frameBuffer[y + x + 1 + width * (k + 6)] = 1;
		}

		for (x = 1; x < 5; x++) {
			setMask(y + x, k + 1);
			setMask(y + 1, k + x + 1);
			setMask(y + 5, k + x);
			setMask(y + x + 1, k + 5);
		}

		for (x = 2; x < 4; x++) {
			frameBuffer[y + x + width * (k + 2)] = 1;
			frameBuffer[y + 2 + width * (k + x + 1)] = 1;
			frameBuffer[y + 4 + width * (k + x)] = 1;
			frameBuffer[y + x + 1 + width * (k + 4)] = 1;
		}
	}

	// Alignment blocks.
	// 插入对齐点: 前景色为二维码，背景色为掩码
	if (version > 1) {
		t = ALIGNMENT_DELTA[version];
		y = width - 7;

		for (; ;) {
			x = width - 7;

			while (x > t - 3) {
				addAlignment(x, y);

				if (x < t) break;

				x -= t;
			}

			if (y <= t + 9) break;

			y -= t;

			addAlignment(6, y);
			addAlignment(y, 6);
		}
	}

	// Single foreground cell.
	// 插入单个前景色单元格: 前景色为二维码，背景色为掩码
	frameBuffer[8 + width * (width - 8)] = 1;

	// Timing gap (mask only).
	// 插入时间间隔: 掩码
	for (y = 0; y < 7; y++) {
		setMask(7, y);
		setMask(width - 8, y);
		setMask(7, y + width - 7);
	}

	for (x = 0; x < 8; x++) {
		setMask(x, 7);
		setMask(x + width - 8, 7);
		setMask(x, width - 8);
	}

	// Reserve mask, format area.
	// 保留掩码，格式化区域
	for (x = 0; x < 9; x++) {
		setMask(x, 8);
	}

	for (x = 0; x < 8; x++) {
		setMask(x + width - 8, 8);
		setMask(8, x);
	}

	for (y = 0; y < 7; y++) {
		setMask(8, y + width - 7);
	}

	// Timing row/column.
	// 插入时间间隔行/列: 掩码
	for (x = 0; x < width - 14; x++) {
		if ((x & 1) > 0) {
			setMask(8 + x, 6);
			setMask(6, 8 + x);
		} else {
			frameBuffer[8 + x + width * 6] = 1;
			frameBuffer[6 + width * (8 + x)] = 1;
		}
	}

	// Version block.
	if (version > 6) {
		t = VERSION_BLOCK[version - 7];
		k = 17;

		for (x = 0; x < 6; x++) {
			for (y = 0; y < 3; y++) {
				if ((1 & (k > 11 ? version >> (k - 12) : t >> k)) > 0) {
					frameBuffer[5 - x + width * (2 - y + width - 11)] = 1;
					frameBuffer[2 - y + width - 11 + width * (5 - x)] = 1;
				} else {
					setMask(5 - x, 2 - y + width - 11);
					setMask(2 - y + width - 11, 5 - x);
				}
				k--;
			}
		}
	}

	// Sync mask bits. Only set above for background cells, so now add the foreground.
	// 同步掩码位。只有上方的背景单元格需要设置，现在添加前景色。
	for (y = 0; y < width; y++) {
		for (x = 0; x <= y; x++) {
			if (frameBuffer[x + width * y] > 0) {
				setMask(x, y);
			}
		}
	}

	// Convert string to bit stream. 8-bit data to QR-coded 8-bit data (numeric, alphanum, or kanji
	// not supported).
	// 将字符串转换为位流。8位数据转换为QR编码的8位数据（不支持数字、字母或汉字）。
	v = str.length;

	// String to array.
	for (i = 0; i < v; i++) {
		eccBuffer[i] = str.charCodeAt(i)!;
	}

	//++++++++++++++++++++==============
	stringBuffer.set(eccBuffer.subarray(0, v));

	// Calculate max string length.
	x = dataBlock * (neccBlock1 + neccBlock2) + neccBlock2;

	if (v >= x - 2) {
		v = x - 2;

		if (version > 9) v--;
	}

	// Shift and re-pack to insert length prefix.
	// 移位并重新打包以插入长度前缀。
	i = v;

	if (version > 9) {
		stringBuffer[i + 2] = 0;
		stringBuffer[i + 3] = 0;

		while (i-- > 0) {
			t = stringBuffer[i];

			stringBuffer[i + 3] |= 255 & (t << 4);
			stringBuffer[i + 2] = t >> 4;
		}

		stringBuffer[2] |= 255 & (v << 4);
		stringBuffer[1] = v >> 4;
		stringBuffer[0] = 0x40 | (v >> 12);
	} else {
		stringBuffer[i + 1] = 0;
		stringBuffer[i + 2] = 0;

		while (i-- > 0) {
			t = stringBuffer[i];

			stringBuffer[i + 2] |= 255 & (t << 4);
			stringBuffer[i + 1] = t >> 4;
		}

		stringBuffer[1] |= 255 & (v << 4);
		stringBuffer[0] = 0x40 | (v >> 4);
	}

	// Fill to end with pad pattern.
	// 用填充模式填充到结束。
	i = v + 3 - (version < 10 ? 1 : 0);

	while (i < x) {
		stringBuffer[i++] = 0xec;
		stringBuffer[i++] = 0x11;
	}

	// Calculate generator polynomial.
	// 计算生成多项式。
	polynomial = new Uint8Array(eccBlock + 1);
	polynomial[0] = 1;

	for (i = 0; i < eccBlock; i++) {
		polynomial[i + 1] = 1;

		for (j = i; j > 0; j--) {
			polynomial[j] =
				polynomial[j] > 0
					? polynomial[j - 1] ^ GALOIS_EXPONENT[modN(GALOIS_LOG[polynomial[j]] + i)]
					: polynomial[j - 1];
		}

		polynomial[0] = GALOIS_EXPONENT[modN(GALOIS_LOG[polynomial[0]] + i)];
	}

	// Use logs for generator polynomial to save calculation step.
	// 使用对数计算生成多项式以节省计算步骤。
	for (i = 0; i < eccBlock; i++) {
		polynomial[i] = GALOIS_LOG[polynomial[i]];
	}

	// Append ECC to data buffer.
	// 将ECC附加到数据缓冲区。
	k = x;
	y = 0;

	for (i = 0; i < neccBlock1; i++) {
		appendData(y, dataBlock, k, eccBlock);

		y += dataBlock;
		k += eccBlock;
	}

	for (i = 0; i < neccBlock2; i++) {
		appendData(y, dataBlock + 1, k, eccBlock);

		y += dataBlock + 1;
		k += eccBlock;
	}

	// Interleave blocks.
	y = 0;

	for (i = 0; i < dataBlock; i++) {
		for (j = 0; j < neccBlock1; j++) {
			eccBuffer[y++] = stringBuffer[i + j * dataBlock];
		}

		for (j = 0; j < neccBlock2; j++) {
			eccBuffer[y++] = stringBuffer[neccBlock1 * dataBlock + i + j * (dataBlock + 1)];
		}
	}

	for (j = 0; j < neccBlock2; j++) {
		eccBuffer[y++] = stringBuffer[neccBlock1 * dataBlock + i + j * (dataBlock + 1)];
	}

	for (i = 0; i < eccBlock; i++) {
		for (j = 0; j < neccBlock1 + neccBlock2; j++) {
			eccBuffer[y++] = stringBuffer[x + i + j * eccBlock];
		}
	}

	stringBuffer.set(eccBuffer);

	// Pack bits into frame avoiding masked area.
	// 将位流打包到帧中，避免掩码区域。
	x = width - 1;
	y = width - 1;
	k = 1;
	v = 1;

	// inteleaved data and ECC codes.
	// 交错数据和ECC代码。
	m = (dataBlock + eccBlock) * (neccBlock1 + neccBlock2) + neccBlock2;

	for (i = 0; i < m; i++) {
		t = stringBuffer[i];

		for (j = 0; j < 8; j++) {
			if ((0x80 & t) > 0) {
				frameBuffer[x + width * y] = 1;
			}

			// Find next fill position.
			// 找到下一个填充位置。
			do {
				if (v > 0) {
					x--;
				} else {
					x++;

					if (k > 0) {
						if (y != 0) {
							y--;
						} else {
							x -= 2;
							k = k == 0 ? 1 : 0;

							if (x == 6) {
								x--;
								y = 9;
							}
						}
					} else {
						if (y != width - 1) {
							y++;
						} else {
							x -= 2;
							k = k == 0 ? 1 : 0;

							if (x == 6) {
								x--;
								y -= 8;
							}
						}
					}
				}

				v = v == 0 ? 1 : 0;
			} while (isMasked(x, y));
			t <<= 1;
		}
	}

	// Save pre-mask copy of frame.
	const frameBufferCopy = frameBuffer.slice(0);

	t = 0;
	y = 30000;

	// Using `for` instead of `while` since in original Arduino code if an early mask was *good
	// enough* it wouldn't try for a better one since they get more complex and take longer.
	// 使用`for`而不是`while`，因为在原始Arduino代码中，如果早期掩码足够好，它不会尝试更好的掩码，因为它们变得更复杂并需要更长的时间。
	for (k = 0; k < 8; k++) {
		// Returns foreground-background imbalance.
		// 返回前景色和背景色的不平衡。
		applyMask(k);

		x = checkBadness();

		// Is current mask better than previous best?
		// 当前掩码是否比之前的最佳掩码更好？
		if (x < y) {
			y = x;
			t = k;
		}

		// Don't increment `i` to a void redoing mask.
		// 不要增加`i`以避免重新做掩码。
		if (t == 7) break;

		// Reset for next pass.
		// 重置下一个循环。
		frameBuffer.set(frameBufferCopy);
	}

	// Redo best mask as none were *good enough* (i.e. last wasn't `t`).
	// 重做最佳掩码，因为没有一个掩码足够好（即最后一个不是`t`）。
	if (t != k) {
		// Reset buffer to pre-mask state before applying the best one
		frameBuffer.set(frameBufferCopy);
		applyMask(t);
	}

	// Add in final mask/ECC level bytes.
	// 添加最终的掩码/ECC级别字节。
	y = FINAL_FORMAT[t + ((eccLevel - 1) << 3)];

	// Low byte.
	for (k = 0; k < 8; k++) {
		if ((y & 1) > 0) {
			frameBuffer[width - 1 - k + width * 8] = 1;

			if (k < 6) {
				frameBuffer[8 + width * k] = 1;
			} else {
				frameBuffer[8 + width * (k + 1)] = 1;
			}
		}
		y >>= 1;
	}

	// High byte.
	for (k = 0; k < 7; k++) {
		if ((y & 1) > 0) {
			frameBuffer[8 + width * (width - 7 + k)] = 1;

			if (k > 0) {
				frameBuffer[6 - k + width * 8] = 1;
			} else {
				frameBuffer[7 + width * 8] = 1;
			}
		}
		y >>= 1;
	}

	// Finally, return the image data.
	return {
		frameBuffer: frameBuffer,
		width: width
	} as GenerateFrameResult;
}

export default {
  slots: {
    root: 'relative',
  },
}

export const qrcodeMode = ['rect', 'circular', 'line', 'rectSmall']

/**
 * 导入所需的工具函数和依赖
 */
import { generateFrame } from "./qrcode";

export type ClQrcodeMode = "rect" | "circular" | "line" | "rectSmall";

export enum eccLevel {
	L = "L",
	M = "M",
	Q = "Q",
	H = "H"
}

export type QrcodeOptions = {
	ecc: eccLevel; // 纠错级别
	text: string; // 二维码内容
	size: number; // 二维码尺寸,单位px
	foreground: string; // 前景色
	background: string; // 背景色
	padding: number; // 内边距
	logo: string; // logo图片地址
	logoSize: number; // logo尺寸
	mode: ClQrcodeMode; // 二维码样式模式
	pdColor: string | null; // 定位点颜色
	pdRadius: number; // 定位图案圆角半径（兼容旧版）
	pdOuterRadius?: number; // 码眼外框圆角半径
	pdInnerRadius?: number; // 码眼内点圆角半径
	dotsGradient?: any;
	dotsImage?: string | null;
	backgroundGradient?: any;
	backgroundTransparent?: boolean;
	logoOptions?: any;
	cornersSquareGradient?: any;
	cornersDotGradient?: any;
	cornersSquareOptions?: any;
	cornersDotOptions?: any;
};

/**
 * 绘制圆角矩形
 */
function drawRoundedRect(
	ctx: any,
	x: number,
	y: number,
	width: number,
	height: number,
	radius: number
) {
	if (radius <= 0) {
		ctx.fillRect(x, y, width, height);
		return;
	}

	const maxRadius = Math.min(width, height) / 2;
	const r = Math.min(radius, maxRadius);

	ctx.beginPath();
	ctx.moveTo(x + r, y);
	ctx.lineTo(x + width - r, y);
	ctx.arcTo(x + width, y, x + width, y + r, r);
	ctx.lineTo(x + width, y + height - r);
	ctx.arcTo(x + width, y + height, x + width - r, y + height, r);
	ctx.lineTo(x + r, y + height);
	ctx.arcTo(x, y + height, x, y + height - r, r);
	ctx.lineTo(x, y + r);
	ctx.arcTo(x, y, x + r, y, r);
	ctx.closePath();
	ctx.fill();
}

function createFillStyle(ctx: any, styleConfig: any, size: number) {
	if (!styleConfig) return null;
	try {
		if (styleConfig.type === 'linear') {
			let x1 = 0, y1 = 0, x2 = 0, y2 = 0;
			switch (styleConfig.direction) {
				case 'horizontal': x2 = size; break;
				case 'vertical': y2 = size; break;
				case 'diagonal': x2 = size; y2 = size; break;
				case 'center': x1 = size / 2; y1 = size / 2; x2 = size; y2 = size; break;
				default: x2 = size; break;
			}
			const grd = ctx.createLinearGradient(x1, y1, x2, y2);
			if (styleConfig.colorStops) {
				styleConfig.colorStops.forEach((stop: any) => {
					grd.addColorStop(stop.offset, stop.color);
				});
			}
			return grd;
		} else if (styleConfig.type === 'radial') {
			const grd = ctx.createCircularGradient ? ctx.createCircularGradient(size / 2, size / 2, size / 2) : ctx.createLinearGradient(0, 0, size, size);
			if (styleConfig.colorStops) {
				styleConfig.colorStops.forEach((stop: any) => {
					grd.addColorStop(stop.offset, stop.color);
				});
			}
			return grd;
		}
	} catch (e) {
		console.warn('创建渐变失败', e);
	}
	return null;
}

function setFillStyle(ctx: any, fillStyle: any) {
	if (typeof ctx.setFillStyle === 'function') {
		ctx.setFillStyle(fillStyle);
		return;
	}
	ctx.fillStyle = fillStyle;
}

function flushDraw(ctx: any) {
	if (typeof ctx.draw === 'function') {
		ctx.draw(false);
	}
}

async function loadImageSource(src: string, canvasNode?: any) {
	if (canvasNode?.createImage) {
		const image = canvasNode.createImage();
		await new Promise<void>((resolve, reject) => {
			image.onload = () => resolve();
			image.onerror = (err: any) => reject(err);
			image.src = src;
		});
		return image;
	}

	const imageInfo = await new Promise<any>((resolve, reject) => {
		uni.getImageInfo({
			src,
			success: (res) => {
				if (
					!res.path.startsWith('http://') &&
					!res.path.startsWith('https://') &&
					!res.path.startsWith('/') &&
					!res.path.startsWith('data:') &&
					!res.path.startsWith('wxfile://')
				) {
					res.path = '/' + res.path;
				}
				resolve(res);
			},
			fail: reject
		});
	});

	return imageInfo.path;
}

/**
 * 绘制定位图案（码眼）
 */
function drawPositionPattern(
	ctx: any,
	startX: number,
	startY: number,
	px: number,
	pdSquareFillStyle: any,
	pdDotFillStyle: any,
	background: string,
	outerRadius: number,
	centerRadius: number
) {
	const patternSize = px * 7;

	const safeOuterRadius = Math.max(0, outerRadius);
	const safeCenterRadius = Math.max(0, centerRadius);

	setFillStyle(ctx, pdSquareFillStyle);
	drawRoundedRect(ctx, startX, startY, patternSize, patternSize, safeOuterRadius);

	if (background !== 'transparent') {
		setFillStyle(ctx, background);
		const innerStartX = startX + px;
		const innerStartY = startY + px;
		const innerSize = px * 5;
		const innerRadius = Math.max(0, safeOuterRadius - px);
		drawRoundedRect(ctx, innerStartX, innerStartY, innerSize, innerSize, innerRadius);
	} else {
		// 在透明背景下，如果只用上面的方法，内圈会实心。所以我们改用 clip+填充 的方式，或者绘制两层来避免遮挡：
		// 实际上透明背景应该清空内圈，由于 Canvas 是叠加的，这里比较难直接在图案上抠洞，
		// 通常做法是用 clip 或 composite 模式。为了简单处理，透明背景不填充中间层
		// 由于第一步已经填充了实心外框，如果背景透明，中间会是一整块。
		// 这里我们用 clearRect 加上 clear 的圆角实现不太容易。
		// 采用最保险的方式：用 path 绘制一个带有内孔的圆角矩形环
	}

	// 我们修改 drawPositionPattern 的实现，让它支持带洞的圆环和中心的点
	ctx.beginPath();

	// 绘制外环（顺时针）
	const r = Math.min(safeOuterRadius, patternSize / 2);
	if (r <= 0) {
		ctx.moveTo(startX, startY);
		ctx.lineTo(startX + patternSize, startY);
		ctx.lineTo(startX + patternSize, startY + patternSize);
		ctx.lineTo(startX, startY + patternSize);
		ctx.lineTo(startX, startY);
	} else {
		ctx.moveTo(startX + r, startY);
		ctx.lineTo(startX + patternSize - r, startY);
		ctx.arcTo(startX + patternSize, startY, startX + patternSize, startY + r, r);
		ctx.lineTo(startX + patternSize, startY + patternSize - r);
		ctx.arcTo(startX + patternSize, startY + patternSize, startX + patternSize - r, startY + patternSize, r);
		ctx.lineTo(startX + r, startY + patternSize);
		ctx.arcTo(startX, startY + patternSize, startX, startY + patternSize - r, r);
		ctx.lineTo(startX, startY + r);
		ctx.arcTo(startX, startY, startX + r, startY, r);
	}

	// 绘制内环（逆时针）以便留空
	const innerStartX = startX + px;
	const innerStartY = startY + px;
	const innerSize = px * 5;
	const innerR = Math.max(0, r - px);

	if (innerR <= 0) {
		ctx.moveTo(innerStartX, innerStartY);
		ctx.lineTo(innerStartX, innerStartY + innerSize);
		ctx.lineTo(innerStartX + innerSize, innerStartY + innerSize);
		ctx.lineTo(innerStartX + innerSize, innerStartY);
		ctx.lineTo(innerStartX, innerStartY);
	} else {
		ctx.moveTo(innerStartX + innerR, innerStartY);
		ctx.arcTo(innerStartX, innerStartY, innerStartX, innerStartY + innerR, innerR);
		ctx.lineTo(innerStartX, innerStartY + innerSize - innerR);
		ctx.arcTo(innerStartX, innerStartY + innerSize, innerStartX + innerR, innerStartY + innerSize, innerR);
		ctx.lineTo(innerStartX + innerSize - innerR, innerStartY + innerSize);
		ctx.arcTo(innerStartX + innerSize, innerStartY + innerSize, innerStartX + innerSize, innerStartY + innerSize - innerR, innerR);
		ctx.lineTo(innerStartX + innerSize, innerStartY + innerR);
		ctx.arcTo(innerStartX + innerSize, innerStartY, innerStartX + innerSize - innerR, innerStartY, innerR);
	}
	ctx.closePath();

	setFillStyle(ctx, pdSquareFillStyle);
	ctx.fill('evenodd'); // 用 evenodd 填充带洞的多边形

	// 绘制中心点
	setFillStyle(ctx, pdDotFillStyle);
	const centerStartX = startX + px * 2;
	const centerStartY = startY + px * 2;
	const centerSize = px * 3;
	drawRoundedRect(ctx, centerStartX, centerStartY, centerSize, centerSize, safeCenterRadius);
}

/**
 * 在二维码中心绘制Logo
 */
function drawLogo(ctx: any, options: QrcodeOptions, imageSource: any) {
	ctx.save();

	const contentSize = options.size - options.padding * 2;
	const contentCenterX = options.padding + contentSize / 2;
	const contentCenterY = options.padding + contentSize / 2;

	let logoSize = options.logoSize;
	if (options.logoOptions && options.logoOptions.size) {
		switch (options.logoOptions.size) {
			case 'small': logoSize = 30; break;
			case 'large': logoSize = 60; break;
			default: logoSize = 45; break; // medium
		}
	}

	let backgroundPadding = 3;
	if (options.logoOptions && options.logoOptions.margin) {
		switch (options.logoOptions.margin) {
			case 'none': backgroundPadding = 0; break;
			case 'small': backgroundPadding = 3; break;
			case 'medium': backgroundPadding = 6; break;
			case 'large': backgroundPadding = 10; break;
		}
	}

	const backgroundSize = logoSize + backgroundPadding * 2;
	const backgroundX = contentCenterX - backgroundSize / 2;
	const backgroundY = contentCenterY - backgroundSize / 2;

	let cornerRadius = Math.min(backgroundSize * 0.1, 6);
	if (options.logoOptions && options.logoOptions.shape) {
		switch (options.logoOptions.shape) {
			case 'rectangle': cornerRadius = 0; break;
			case 'circle': cornerRadius = backgroundSize / 2; break;
			case 'rounded-rectangle': cornerRadius = Math.min(backgroundSize * 0.2, 12); break;
		}
	}

	if (options.logoOptions && options.logoOptions.shadow) {
		ctx.shadowColor = 'rgba(0, 0, 0, 0.2)';
		ctx.shadowBlur = 10;
		ctx.shadowOffsetX = 0;
		ctx.shadowOffsetY = 4;
	}

	// 绘制Logo背景
	if (!options.logoOptions || options.logoOptions.hideBackgroundDots !== false) {
		setFillStyle(ctx, options.backgroundTransparent ? '#ffffff' : options.background);
		drawRoundedRect(ctx, backgroundX, backgroundY, backgroundSize, backgroundSize, cornerRadius);
	}

	// 重置阴影，避免影响图片
	ctx.shadowColor = 'transparent';
	ctx.shadowBlur = 0;
	ctx.shadowOffsetX = 0;
	ctx.shadowOffsetY = 0;

	// 绘制图片（如果需要裁剪的话可以加clip）
	const logoX = contentCenterX - logoSize / 2;
	const logoY = contentCenterY - logoSize / 2;

	if (cornerRadius > 0) {
		ctx.save();
		ctx.beginPath();
		const innerRadius = Math.max(0, cornerRadius - backgroundPadding);
		ctx.moveTo(logoX + innerRadius, logoY);
		ctx.lineTo(logoX + logoSize - innerRadius, logoY);
		ctx.arcTo(logoX + logoSize, logoY, logoX + logoSize, logoY + innerRadius, innerRadius);
		ctx.lineTo(logoX + logoSize, logoY + logoSize - innerRadius);
		ctx.arcTo(logoX + logoSize, logoY + logoSize, logoX + logoSize - innerRadius, logoY + logoSize, innerRadius);
		ctx.lineTo(logoX + innerRadius, logoY + logoSize);
		ctx.arcTo(logoX, logoY + logoSize, logoX, logoY + logoSize - innerRadius, innerRadius);
		ctx.lineTo(logoX, logoY + innerRadius);
		ctx.arcTo(logoX, logoY, logoX + innerRadius, logoY, innerRadius);
		ctx.closePath();
		ctx.clip();
	}

	ctx.drawImage(imageSource, logoX, logoY, logoSize, logoSize);

	if (cornerRadius > 0) {
		ctx.restore();
	}

	ctx.restore();
}

/**
 * 绘制二维码到Canvas上下文
 */
export async function drawQrcode(ctx: any, options: QrcodeOptions, canvasNode?: any) {
	if (!ctx) return;

	// 生成二维码数据矩阵
	const frame = generateFrame(options.text, options.ecc);
	const points = frame.frameBuffer; // 点阵数据
	const width = frame.width; // 矩阵宽度

	// 计算二维码内容区域大小
	const contentSize = options.size - options.padding * 2;
	const px = contentSize / width;
	const offsetX = options.padding;
	const offsetY = options.padding;

	// 绘制整个画布背景
	if (options.backgroundTransparent) {
		ctx.clearRect(0, 0, options.size, options.size);
	} else {
		const bgGradient = createFillStyle(ctx, options.backgroundGradient, options.size);
		setFillStyle(ctx, bgGradient || options.background);
		ctx.fillRect(0, 0, options.size, options.size);
	}

	function isPositionDetectionPattern(i: number, j: number, width: number): boolean {
		if (i < 7 && j < 7) return true; // 左上角
		if (i > width - 8 && j < 7) return true; // 右上角
		if (i < 7 && j > width - 8) return true; // 左下角
		return false;
	}

	function isInLogoArea(
		i: number,
		j: number,
		width: number,
		baseLogoSize: number,
		px: number
	): boolean {
		let logoSize = baseLogoSize;
		if (options.logoOptions && options.logoOptions.size) {
			switch (options.logoOptions.size) {
				case 'small': logoSize = 30; break;
				case 'large': logoSize = 60; break;
				default: logoSize = 45; break; // medium
			}
		}
		let backgroundPadding = 3;
		if (options.logoOptions && options.logoOptions.margin) {
			switch (options.logoOptions.margin) {
				case 'none': backgroundPadding = 0; break;
				case 'small': backgroundPadding = 3; break;
				case 'medium': backgroundPadding = 6; break;
				case 'large': backgroundPadding = 10; break;
			}
		}

		if (logoSize <= 0) return false;

		const maxLogoRatio = 0.3;
		const maxLogoPoints = Math.floor(width * maxLogoRatio);
		const logoPoints = Math.min(Math.ceil((logoSize + backgroundPadding * 2) / px), maxLogoPoints);

		const buffer = logoPoints > width * 0.1 ? 1 : 0;
		const totalLogoPoints = logoPoints + buffer * 2;

		const centerI = Math.floor(width / 2);
		const centerJ = Math.floor(width / 2);

		const halfSize = Math.floor(totalLogoPoints / 2);
		const minI = centerI - halfSize;
		const maxI = centerI + halfSize;
		const minJ = centerJ - halfSize;
		const maxJ = centerJ + halfSize;

		return i >= minI && i <= maxI && j >= minJ && j <= maxJ;
	}

	const pdColor = options.pdColor ?? options.foreground;

	const baseRadius = options.pdRadius;
	const outerRadius = options.pdOuterRadius !== undefined ? options.pdOuterRadius : baseRadius;
	const centerRadius = options.pdInnerRadius !== undefined ? options.pdInnerRadius : Math.max(0, outerRadius - px * 2);

	const fgGradient = createFillStyle(ctx, options.dotsGradient, options.size);
	const fgStyle = fgGradient || options.foreground;

	const pdSquareGradient = options.cornersSquareGradient || options.dotsGradient;
	const pdDotGradient = options.cornersDotGradient || options.dotsGradient;

	const pdSquareFillStyle = createFillStyle(ctx, pdSquareGradient, options.size) || (options.cornersSquareOptions && options.cornersSquareOptions.color) || ((options.pdColor && options.pdColor !== options.foreground) ? options.pdColor : fgStyle);
	const pdDotFillStyle = createFillStyle(ctx, pdDotGradient, options.size) || (options.cornersDotOptions && options.cornersDotOptions.color) || ((options.pdColor && options.pdColor !== options.foreground) ? options.pdColor : fgStyle);

	drawPositionPattern(ctx, offsetX, offsetY, px, pdSquareFillStyle, pdDotFillStyle, options.backgroundTransparent ? 'transparent' : options.background, outerRadius, centerRadius);
	drawPositionPattern(
		ctx,
		offsetX + (width - 7) * px,
		offsetY,
		px,
		pdSquareFillStyle,
		pdDotFillStyle,
		options.backgroundTransparent ? 'transparent' : options.background,
		outerRadius,
		centerRadius
	);
	drawPositionPattern(
		ctx,
		offsetX,
		offsetY + (width - 7) * px,
		px,
		pdSquareFillStyle,
		pdDotFillStyle,
		options.backgroundTransparent ? 'transparent' : options.background,
		outerRadius,
		centerRadius
	);

	const dot = px * 0.1;

	// 加载前景图
	let fgImageSource: any = null;
	if (options.dotsImage) {
		try {
			let src = options.dotsImage;
			// #ifdef MP-WEIXIN
			// 对于 http/https 或以 /、data: 开头的路径，直接使用原路径
			if (
				!src.startsWith('http://') &&
				!src.startsWith('https://') &&
				!src.startsWith('/') &&
				!src.startsWith('data:')
			) {
				// 微信小程序中 uni.getImageInfo 需要的是绝对路径，如果是 static/xx 则补上 /
				src = '/' + src;
			}
			// #endif
			fgImageSource = await loadImageSource(src, canvasNode);
		} catch (e) {
			console.error("加载前景图失败", e);
		}
	}

	if (fgImageSource) {
		ctx.save();
		ctx.beginPath();
	}

	for (let i = 0; i < width; i++) {
		for (let j = 0; j < width; j++) {
			if (points[j * width + i] > 0) {
				if (isPositionDetectionPattern(i, j, width)) {
					continue;
				}

				if (options.logo != "" && isInLogoArea(i, j, width, options.logoSize, px)) {
					if (!options.logoOptions || options.logoOptions.hideBackgroundDots !== false) {
						continue;
					}
				}

				if (!fgImageSource) {
					setFillStyle(ctx, fgStyle);
				}

				const x = offsetX + px * i;
				const y = offsetY + px * j;

				switch (options.mode) {
					case "line":
						if (fgImageSource) ctx.rect(x, y, px, px / 2);
						else ctx.fillRect(x, y, px, px / 2);
						break;

					case "circular":
						if (!fgImageSource) ctx.beginPath();
						const rx = x + px / 2 - dot;
						const ry = y + px / 2 - dot;
						if (fgImageSource) ctx.moveTo(rx + px / 2 - dot, ry);
						ctx.arc(rx, ry, px / 2 - dot, 0, 2 * Math.PI);
						if (!fgImageSource) {
							ctx.fill();
							ctx.closePath();
						}
						break;

					case "rectSmall":
						if (fgImageSource) ctx.rect(x + dot, y + dot, px - dot * 2, px - dot * 2);
						else ctx.fillRect(x + dot, y + dot, px - dot * 2, px - dot * 2);
						break;

					default:
						if (fgImageSource) ctx.rect(x, y, px, px);
						else ctx.fillRect(x, y, px, px);
				}
			}
		}
	}

	if (fgImageSource) {
		ctx.clip();
		ctx.drawImage(fgImageSource, 0, 0, options.size, options.size);
		ctx.restore();
	}

	if (options.logo != "") {
		try {
			let logoSrc = options.logo;

			// #ifdef H5
			if (logoSrc.startsWith("http")) {
				try {
					logoSrc = await new Promise<string>((resolve, reject) => {
						const img = new Image();
						img.crossOrigin = "Anonymous";
						img.onload = () => {
							const canvas = document.createElement("canvas");
							canvas.width = img.width;
							canvas.height = img.height;
							const context = canvas.getContext("2d");
							context?.drawImage(img, 0, 0);
							try {
								const dataUrl = canvas.toDataURL("image/png");
								resolve(dataUrl);
							} catch (err) {
								reject(err);
							}
						};
						img.onerror = reject;
						img.src = logoSrc;
					});
				} catch (e) {
					console.warn("Logo CORS load failed, using original URL. Canvas export may fail.", e);
				}
			}
			// #endif

			// #ifdef MP-WEIXIN
			// 对于 http/https 或以 /、data: 开头的路径，直接使用原路径
			if (
				!logoSrc.startsWith('http://') &&
				!logoSrc.startsWith('https://') &&
				!logoSrc.startsWith('/') &&
				!logoSrc.startsWith('data:')
			) {
				// 微信小程序中 uni.getImageInfo 需要的是绝对路径，如果是 static/xx 则补上 /
				logoSrc = '/' + logoSrc;
			}
